/* Connected filters for the historical snapshot; no automatic model deployment. */
(()=>{let cube=null,stock=null,stockPromise=null,planPage=0,planFiltered=[];const marked=new Map(),field={estrategico:'strategic',alta_tecnologia:'high'},originalOverview=renderOverview;
const sum=(rs,k)=>rs.reduce((a,r)=>a+r[k],0),selected=()=>({round:$('round').value,uf:$('overview-uf').value,result:$('overview-result').value,group:$('group').value});
function rowsFor(s){return cube.filter(r=>(!s.round||r.r===+s.round)&&(!s.uf||r.u===s.uf)&&(!s.result||r.s===s.result)&&(s.group==='todas'||r[field[s.group]]))}
function chart(rs,sel){
 const metric=$('round-metric').value,cumulative=$('round-cumulative').checked,isMoney=metric==='bids';
 const labels={bids:'Lances vencedores',included:'Áreas incluídas',awarded:'Áreas arrematadas'};
 const explain={bids:'Quanto foi ofertado pelos vencedores? Estes são lances registrados, em reais nominais. Não representam pagamentos recebidos nem previsão de receita.',included:'Quantas áreas aparecem em cada rodada? Contamos ocorrências por rodada, inclusive a oferta social e o edital cancelado. A mesma área pode aparecer em mais de uma rodada.',awarded:'Quantas áreas tiveram arrematação comercial? Conquista sem disputa financeira é outro resultado. Nas rodadas 6 e 7, esta comparação comercial não se aplica.'};
 $('metric-explanation').textContent=explain[metric];
 let total=0;const points=Array.from({length:8},(_,i)=>{const n=i+1,rr=rs.filter(r=>r.r===n),v=metric==='bids'?sum(rr,'v'):metric==='included'?sum(rr,'n'):sum(rr.filter(r=>r.s==='Arrematada'&&![6,7].includes(n)),'n');return {n,v,t:total+=v,outside:!!sel.round&&+sel.round!==n,na:metric==='awarded'&&[6,7].includes(n)}});
 const max=Math.max(1,...points.map(r=>cumulative?r.t:r.v)),x=i=>72+i*68,y=v=>238-175*v/max,compact=v=>isMoney?(v/1e6).toLocaleString('pt-BR',{maximumFractionDigits:1}):N(v),exact=v=>isMoney?M(v):N(v);
 let svg='<svg viewBox="0 0 650 300" role="group" aria-label="Valores por rodada. Clique para filtrar."><title>'+labels[metric]+'</title>';
 for(let i=0;i<=3;i++){const v=max*i/3;svg+=`<line x1="60" x2="625" y1="${y(v)}" y2="${y(v)}" stroke="#dce3eb"/><text x="52" y="${y(v)+4}" text-anchor="end">${compact(v)}</text>`}
 svg+=`<text x="60" y="20">${isMoney?'R$ milhões':'Número de ocorrências'}</text>`;
 if(cumulative)svg+=`<polyline points="${points.map((r,i)=>(x(i)+19)+','+y(r.t)).join(' ')}" fill="none" pointer-events="none" stroke="#168821" stroke-width="3"/>`;
 points.forEach((r,i)=>{const label=r.outside?'—':r.na?'N/A':compact(r.v),color=r.outside?'#ccd5e2':[6,7].includes(r.n)?'#69788a':'#1351b4';svg+=`<g tabindex="0" role="button" data-pick-round="${r.n}" aria-pressed="${+sel.round===r.n}" aria-label="${r.n}ª rodada: ${r.outside?'fora do filtro':r.na?'não se aplica':exact(r.v)}. Clique para filtrar."><title>${r.n}ª: ${r.outside?'Fora do filtro':r.na?'Não se aplica':exact(r.v)}</title><rect x="${x(i)}" y="${y(r.v)}" width="38" height="${Math.max(2,238-y(r.v))}" fill="${color}" rx="3"/><text class="value-label" x="${x(i)+19}" y="${y(r.v)-9}" text-anchor="middle">${label}</text><text x="${x(i)+19}" y="266" text-anchor="middle">${r.n}ª${[6,7].includes(r.n)?'*':''}</text><rect x="${x(i)-4}" y="35" width=" fifty" height="250" fill="transparent"/></g>`;
 if(cumulative&&!r.outside){svg+=`<circle cx="${x(i)+19}" cy="${y(r.t)}" r="4" fill="#168821"/><text class="sum-label" x="${x(i)+19}" y="${y(r.t)-27}" text-anchor="middle">${compact(r.t)}</text>`}});
 svg+='</svg>';
 return `<div class="time-legend"><span><i></i>${labels[metric]}</span>${cumulative?'<span><i class="line-key"></i>Acumulado (rótulos verdes)</span>':''}</div><div class="round-scroll">${svg.replaceAll('width=" fifty"','width="50"')}</div><p class="caption">${isMoney?'Rótulos em milhões de reais; valores exatos abaixo. ':''}* 6ª: avaliação social; 7ª: edital cancelado. ${metric==='included'?'As áreas destas ofertas entram na contagem.':metric==='awarded'?'N/A = não se aplica; não é taxa zero de sucesso.':'Contribuição financeira zero não significa área sem valor.'} Traço = rodada fora do filtro.</p><details><summary>Conferir os valores exatos</summary><div class="table-wrap">${table(['Rodada',labels[metric],...(cumulative?['Acumulado']:[])],points.map(r=>[r.n+'ª',r.outside?'Fora do filtro':r.na?'Não se aplica':exact(r.v),...(cumulative?[r.outside?'—':exact(r.t)]:[])]))}</div></details>`;
}

renderOverview=function(){originalOverview();if(!cube)return;const s=selected(),rs=rowsFor(s),count=sum(rs,'n'),money=sum(rs,'v'),wins=sum(rs.filter(r=>r.s==='Arrematada'&&![6,7].includes(r.r)),'n'),free=sum(rs.filter(r=>r.s==='Livre'),'n');
$('kpis').innerHTML=[['Lances vencedores',M(money),'Não equivale a pagamento recebido',''],['Áreas incluídas',N(count),'Ocorrências de área por rodada',''],['Arrematações',N(wins),'Resultado comercial com lance vencedor','Arrematada'],['Áreas livres',N(free),'Inclui resultado social, quando selecionado','Livre']].map(([a,b,c,result])=>`<article class="kpi" ${result?`role="button" tabindex="0" data-pick-result="${result}" aria-label="Filtrar ${result}"`:''}><span>${a}</span><strong>${b}</strong><small>${c}</small></article>`).join('');
$('roundchart').innerHTML=chart(rs,s);const status=[...new Set(rs.map(r=>r.s))].sort(),mx=Math.max(...status.map(t=>sum(rs.filter(r=>r.s===t),'n')),1);$('outcomes').innerHTML=status.map(t=>{const n=sum(rs.filter(r=>r.s===t),'n');return `<button class="filter-bar" data-pick-result="${E(t)}" aria-pressed="${s.result===t}"><span class="bar-top"><span>${E(t)}</span><b>${N(n)}</b></span><span class="track"><span class="fill" style="width:${100*n/mx}%"></span></span></button>`}).join('')||'<p>Nenhuma ocorrência nesse recorte.</p>';
const states=[...new Set(rs.map(r=>r.u))].map(u=>[u,sum(rs.filter(r=>r.u===u),'n')]).sort((a,b)=>b[1]-a[1]).slice(0,8),sm=Math.max(...states.map(x=>x[1]),1);$('uf-chart').innerHTML=states.map(([u,n])=>`<button class="filter-bar" data-pick-uf="${E(u)}" aria-pressed="${s.uf===u}"><span class="bar-top"><span>${E(u||'Sem UF')}</span><b>${N(n)}</b></span><span class="track"><span class="fill green" style="width:${100*n/sm}%"></span></span></button>`).join('')||'<p>Nenhuma área no recorte.</p>';
const tags=[s.round&&s.round+'ª rodada',s.uf,s.result,s.group!=='todas'&&$('group').selectedOptions[0].text].filter(Boolean);$('active-filters').textContent=tags.length?'Seleção aplicada aos indicadores e gráficos: '+tags.join(' · '):'Todas as oito rodadas. Clique em uma coluna, resultado ou estado para filtrar os indicadores e gráficos.';
const commercial=rs.filter(r=>![6,7].includes(r.r)&&['Arrematada','Conquistada','Livre'].includes(r.s)),valid=sum(commercial,'n'),topRound=Array.from({length:8},(_,i)=>[i+1,sum(rs.filter(r=>r.r===i+1),'v')]).sort((a,b)=>b[1]-a[1])[0];
$('portfolio-insights').innerHTML=`<p><b>${N(count)} ocorrências na carteira selecionada.</b> ${valid?`Nas ${N(valid)} ocorrências com resultado comercial válido, ${P(wins/valid)} foram arrematadas.`:'Não há resultados comerciais válidos neste recorte.'}</p><p>${money?`A ${topRound[0]}ª rodada concentra ${P(topRound[1]/money)} dos lances deste recorte. Isso mostra concentração histórica, não previsão de receita futura.`:'Não há contribuição financeira comparável na seleção. Isso não significa que o valor econômico das áreas seja zero.'}</p><p><b>Próxima ação:</b> examine as áreas que compõem o recorte e confira substâncias, eventos e restrições antes de propor uma carteira.</p>`;
const q=new URLSearchParams();for(const[k,v]of Object.entries(s))if(v&&v!=='todas')q.set(k,v);$('open-filtered-areas').href='acervo.html?'+q;
$('scope').textContent='6ª: avaliação social. 7ª: edital cancelado. Ambas aparecem na série com contribuição financeira zero. Recortes estratégicos usam referência de 2021.'};
['group','round','round-metric','round-cumulative'].forEach(id=>$(id).addEventListener('change',()=>renderOverview()));
function pick(type,value){const ids={round:'round',uf:'overview-uf',result:'overview-result'},x=$(ids[type]);x.value=x.value===value?'':value;renderOverview()}
for(const id of ['roundchart','outcomes','kpis','uf-chart'])$(id).addEventListener('click',e=>{const b=e.target.closest('[data-pick-round],[data-pick-uf],[data-pick-result]');if(!b)return;for(const k of ['round','uf','result'])if(b.dataset['pick'+k[0].toUpperCase()+k.slice(1)]!==undefined)pick(k,b.dataset['pick'+k[0].toUpperCase()+k.slice(1)])});
for(const id of ['roundchart','kpis'])$(id).addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-pick-round],[data-pick-result]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
['overview-uf','overview-result'].forEach(id=>$(id).onchange=renderOverview);$('reset-overview').onclick=()=>{$('round').value='';$('group').value='todas';$('overview-uf').value='';$('overview-result').value='';renderOverview()};
get('pesquisa/cubo_gestao.json').then(d=>{cube=d;$('overview-uf').innerHTML='<option value="">Todos os estados</option>'+[...new Set(d.map(r=>r.u))].sort().map(u=>`<option>${E(u)}</option>`).join('');$('overview-result').innerHTML='<option value="">Todos os resultados</option>'+[...new Set(d.map(r=>r.s))].sort().map(t=>`<option>${E(t)}</option>`).join('');if(summary&&model)renderOverview()}).catch(e=>$('active-filters').textContent=e.message);
const advice={carteira:'Comece com o estoque apto, delimite o recorte e marque candidatas para revisão. A inclusão em edital depende da conferência atual do processo e dos critérios da rodada. O painel não calcula um número ideal de áreas.',minerais:'Selecione o recorte mineral e busque substâncias. A classificação estratégica de 2021 é uma referência do estudo; presença cadastral não comprova reserva, viabilidade ou prioridade atual.',mercado:'Compare localização, substância e área para selecionar oportunidades de estudo. Confira o edital vigente, a poligonal e as condições do processo; esta carteira não comprova que a área esteja aberta a lances.'};
function explainPurpose(){$('planning-advice').textContent=advice[$('planning-purpose').value]}
$('planning-purpose').onchange=explainPurpose;explainPurpose();
const prevNavigate=navigate;navigate=function(id){prevNavigate(id);if(id==='planning')loadStockPlan()};
async function loadStockPlan(){if(stock){planRender();return}if(stockPromise)return;stockPromise=get('pesquisa/estoque_apto.json').then(d=>{stock=d;$('plan-uf').innerHTML='<option value="">Todos os estados</option>'+[...new Set(d.rows.map(r=>r.u))].sort().map(u=>`<option>${E(u)}</option>`).join('');planRender()}).catch(e=>$('plan-note').textContent=e.message).finally(()=>stockPromise=null)}
const fold=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[.\/]/g,'').toLowerCase();
function planRender(){if(!stock)return;const g=$('plan-group').value,uf=$('plan-uf').value,q=fold($('plan-search').value);planFiltered=stock.rows.filter(r=>(!g||r[g])&&(!uf||r.u===uf)&&(!q||fold(r.p+' '+r.m+' '+r.sub).includes(q)));const hectares=r=>Number(r.ha.replaceAll('.','').replace(',','.'))||0;planFiltered.sort($('plan-order').value==='area'?(a,b)=>hectares(b)-hectares(a):(a,b)=>a.p.localeCompare(b.p));
const pages=Math.max(1,Math.ceil(planFiltered.length/20));planPage=Math.min(planPage,pages-1);$('plan-kpis').innerHTML=[['Aptas na base',N(stock.total)],['No recorte',N(planFiltered.length)],['Marcadas para revisão',N(marked.size)],['Coleta do estoque','24/09/2026']].map(([k,v])=>`<article class="kpi"><span>${k}</span><strong>${v}</strong></article>`).join('');$('plan-note').textContent='Aptidão informada no estoque de 24/09/2026. Ordenação descritiva; não é ranking preditivo nem seleção oficial para edital.';$('plan-rows').innerHTML=planFiltered.slice(planPage*20,planPage*20+20).map(r=>`<tr><td><input type="checkbox" data-mark="${E(r.p)}" aria-label="Marcar ${F(r.p)}" ${marked.has(r.p)?'checked':''}></td><td>${F(r.p)}</td><td>${E(r.m)}<br><small>${E(r.u)}</small></td><td>${E(r.sub)}</td><td>${E(r.ha)}</td><td>${E(r.edital||'Sem informação')}<small>${E(r.last||'')}</small></td></tr>`).join('')||'<tr><td colspan="6">Nenhuma área neste recorte.</td></tr>';$('plan-page').textContent=`Página ${planPage+1} de ${pages}`;$('plan-prev').disabled=!planPage;$('plan-next').disabled=planPage+1>=pages;$('plan-export').disabled=!marked.size}
['plan-group','plan-uf','plan-order','plan-search'].forEach(id=>$(id).addEventListener(id==='plan-search'?'input':'change',()=>{planPage=0;planRender()}));$('plan-prev').onclick=()=>{planPage--;planRender()};$('plan-next').onclick=()=>{planPage++;planRender()};$('plan-clear').onclick=()=>{marked.clear();planRender()};$('plan-rows').onchange=e=>{const p=e.target.dataset.mark;if(!p)return;if(e.target.checked)marked.set(p,stock.rows.find(r=>r.p===p));else marked.delete(p);planRender()};$('plan-export').onclick=()=>{const protect=s=>/^[=+@-]/.test(String(s))?"'"+s:s;const csv='processo;UF;municipio;substancias;area_ha;coleta;tipo_selecao\n'+[...marked.values()].map(r=>[F(r.p),r.u,r.m,r.sub,r.ha,'2026-09-24','Carteira manual para revisao; sem previsao validada'].map(s=>'"'+String(protect(s)).replaceAll('"','""')+'"').join(';')).join('\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='mineria-carteira-revisao.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
})();
